#!/usr/bin/env python3
"""
Expands 11 LP21 topic types (across 22 file/topic instances) from 10 → 50 exercises each.
Difficulty spread per topic: 15 easy(1) + 20 medium(2) + 15 hard(3)
Existing 10 exercises are kept; this script adds 40 new ones per instance.
"""

import re, sys

# ─── EXERCISE DATA ─────────────────────────────────────────────────────────────
# Format: (id, type, difficulty, question_DE, question_EN, question_FR, question_IT,
#          answer, options_or_None, hints_DE, dragItems_or_None, dropZones_or_None,
#          dropAnswers_or_None, pairs_or_None)

def mc(id, diff, qDE, qEN, qFR, qIT, ans, opts, h1, h2):
    return {
        "id": id, "type": "multiple-choice", "difficulty": diff,
        "question": qDE, "questionEN": qEN, "questionFR": qFR, "questionIT": qIT,
        "answer": ans, "options": opts, "hints": [h1, h2]
    }

def fib(id, diff, qDE, qEN, qFR, qIT, ans, h1, h2):
    return {
        "id": id, "type": "fill-in-blank", "difficulty": diff,
        "question": qDE, "questionEN": qEN, "questionFR": qFR, "questionIT": qIT,
        "answer": ans, "hints": [h1, h2]
    }

def matching(id, diff, qDE, qEN, qFR, qIT, pairs, h1, h2):
    return {
        "id": id, "type": "matching", "difficulty": diff,
        "question": qDE, "questionEN": qEN, "questionFR": qFR, "questionIT": qIT,
        "answer": "all", "hints": [h1, h2], "pairs": pairs
    }

def dragdrop(id, diff, qDE, qEN, qFR, qIT, items, zones, answers, h1, h2):
    return {
        "id": id, "type": "drag-drop", "difficulty": diff,
        "question": qDE, "questionEN": qEN, "questionFR": qFR, "questionIT": qIT,
        "answer": "all", "hints": [h1, h2],
        "dragItems": items, "dropZones": zones, "dropAnswers": answers
    }

def mem(id, diff, qDE, qEN, qFR, qIT, pairs, h1, h2):
    return {
        "id": id, "type": "memory", "difficulty": diff,
        "question": qDE, "questionEN": qEN, "questionFR": qFR, "questionIT": qIT,
        "answer": "all", "hints": [h1, h2], "pairs": pairs
    }

# ═══════════════════════════════════════════════════════════════════════════════
# TOPIC EXERCISES DATA
# ═══════════════════════════════════════════════════════════════════════════════

